package com.example.takura.operations.application;
import com.example.takura.identity.application.PermissionService; import com.example.takura.identity.domain.StaffPrincipal;
import java.time.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class SettingsService {
 private final JdbcTemplate jdbc; private final PermissionService permissions; private final Clock clock;
 public SettingsService(JdbcTemplate j,PermissionService p,Clock c){jdbc=j;permissions=p;clock=c;}
 public List<Setting> list(StaffPrincipal actor){permissions.require(actor,"settings:read");return jdbc.query("SELECT id,setting_key,setting_value,value_type,environment,status,effective_at,revision,changed_at FROM takura.business_setting ORDER BY setting_key",(r,n)->new Setting((UUID)r.getObject(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getTimestamp(7).toInstant(),r.getLong(8),r.getTimestamp(9).toInstant()));}
 public Setting update(StaffPrincipal actor,UUID id,long expected,Update r){permissions.require(actor,"settings:write");validate(r);int n=jdbc.update("UPDATE takura.business_setting SET setting_value=?,value_type=?,status=?,effective_at=?,revision=revision+1,changed_by=?,changed_at=? WHERE id=? AND revision=?",r.value,r.valueType,r.status,r.effectiveAt,actor.identityId().toString(),clock.instant(),id,expected);if(n==0)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Setting revision is stale");return jdbc.queryForObject("SELECT id,setting_key,setting_value,value_type,environment,status,effective_at,revision,changed_at FROM takura.business_setting WHERE id=?",(x,i)->new Setting((UUID)x.getObject(1),x.getString(2),x.getString(3),x.getString(4),x.getString(5),x.getString(6),x.getTimestamp(7).toInstant(),x.getLong(8),x.getTimestamp(9).toInstant()),id);}
 private static void validate(Update r){Set<String> types=Set.of("STRING","BOOLEAN","INTEGER","DECIMAL","URI","EMAIL","PHONE","DURATION");Set<String> states=Set.of("DEMO","PENDING","CONFIRMED","RETIRED");if(!types.contains(r.valueType)||!states.contains(r.status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid typed setting");try{switch(r.valueType){case"BOOLEAN"-> {if(!Set.of("true","false").contains(r.value))throw new IllegalArgumentException();}case"INTEGER"->Long.parseLong(r.value);case"DECIMAL"->new java.math.BigDecimal(r.value);case"URI"->java.net.URI.create(r.value);case"EMAIL"->{if(!r.value.matches("^[^@]+@[^@]+$"))throw new IllegalArgumentException();}case"DURATION"->Duration.parse(r.value);default->{}}}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Setting value does not match its type");}}
 public record Update(String value,String valueType,String status,Instant effectiveAt){} public record Setting(UUID id,String key,String value,String valueType,String environment,String status,Instant effectiveAt,long revision,Instant changedAt){}
}
